import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.tPQwsn4Z.js";const g=JSON.parse('{"title":"Long-term storage","description":"","frontmatter":{"title":"Long-term storage"},"headers":[],"relativePath":"data/lts.md","filePath":"data/lts.md","lastUpdated":1795011235000}'),s={name:"data/lts.md"};function n(i,e,c,l,h,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="long-term-storage" tabindex="-1">Long-term storage <a class="header-anchor" href="#long-term-storage" aria-label="Permalink to &quot;Long-term storage&quot;">​</a></h1><p>Research data at UNIL is stored on the DCSR NAS, operated by the Scientific Computing and Research Support Unit (DCSR). It has three tiers, described on the <a href="https://wiki.unil.ch/ci/books/research-data-storage/page/general-information" target="_blank" rel="noreferrer">research data storage pages of the UNIL wiki</a>:</p><ul><li><strong>D2c</strong> (data, 2 copies): active data during a project, with an off-site backup and daily snapshots kept for one month.</li><li><strong>LTS</strong> (long-term storage): archiving, typically at the end of a project. Data is kept for about a decade on tape and must be described with metadata when archived.</li><li><strong>D1c</strong> (data, 1 copy): reference data that can be downloaded again from its source. No backup, available on request only.</li></ul><p>Sensitive data has its own path through Tresorit, also documented on the wiki.</p><h2 id="requesting-storage" tabindex="-1">Requesting storage <a class="header-anchor" href="#requesting-storage" aria-label="Permalink to &quot;Requesting storage&quot;">​</a></h2><p>The principal investigator of the project submits the request on the <a href="https://requests.dcsr.unil.ch" target="_blank" rel="noreferrer">DCSR request form</a>. Once the DCSR has accepted it and the PI has granted you access, the share can be mounted from your laptop or, if you have cluster access, reached directly under <code>/nas</code>. For computations, copy data from the NAS to the fast cluster storage first.</p><h2 id="fgse-procedure" tabindex="-1">FGSE procedure <a class="header-anchor" href="#fgse-procedure" aria-label="Permalink to &quot;FGSE procedure&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">In preparation</p><p>The FGSE-specific procedure for long-term storage, from what to archive and how to describe it to who to contact, is being worked out and will be published here. In the meantime, contact the Geocomputing Centre at <a href="mailto:sgc@unil.ch" target="_blank" rel="noreferrer">sgc@unil.ch</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="https://wiki.unil.ch/ci/books/research-data-storage" target="_blank" rel="noreferrer">Research data storage</a> on the UNIL wiki, including S3 storage and large file transfer.</li><li><a href="https://www.unil.ch/fgse/en/home/menuinst/recherche/geocomputing-centre/ressources.html" target="_blank" rel="noreferrer">Resources of the Centre</a> on unil.ch, which lists the DCSR storage and transfer services.</li><li><a href="/previews/pr-15/data/datasets">Shared datasets</a> for the large reference datasets kept on Curnagl.</li></ul>',10)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
